// src/shared/canonical-json.ts
var MAX_DEPTH = 100;
function canonicalStringify(value) {
  return canonicalStringifyInner(value, new WeakSet, 0);
}
function canonicalStringifyInner(value, seen, depth) {
  if (depth > MAX_DEPTH)
    return '"[MaxDepth]"';
  if (value === undefined)
    return "null";
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value) ?? "null";
  }
  if (seen.has(value))
    return '"[Circular]"';
  seen.add(value);
  let result;
  if (Array.isArray(value)) {
    const parts = value.map((e) => canonicalStringifyInner(e, seen, depth + 1));
    result = `[${parts.join(",")}]`;
  } else {
    const obj = value;
    const sortedKeys = Object.keys(obj).filter((k) => obj[k] !== undefined).sort();
    const parts = sortedKeys.map((k) => `${JSON.stringify(k)}:${canonicalStringifyInner(obj[k], seen, depth + 1)}`);
    result = `{${parts.join(",")}}`;
  }
  seen.delete(value);
  return result;
}

